mat2 rot2d(float ang)
{
    float s=sin(ang);
    float c=cos(ang);
    return mat2(c,-s,s,c);
}

float funtio(float x, float i, float a)
{
    return (a-i)*(3.*x*x-2.*x*x*x)+i;
}

vec2 iSqu(vec2 z)
{
    return vec2(z.x*z.x-z.y*z.y,2.*z.x*z.y);
}

float map(vec3 p)
{
    //return length(iSqu(p.xy))-p.z;
    //return 2.*sin(p.x)*sin(p.y)-p.z;
    //return length(p)-1.;
    //return (sin(p.x)-p.y)-(cos(p.x)-p.z);

    float f=pow(length(p.xy)/r2,2.)*512.;
    float fre1=texelFetch(iChannel0,ivec2(f,0),0).x;
    float fre2=texelFetch(iChannel0,ivec2(f+1.,0),0).x;
    f=funtio(fract(f),fre1,fre2);
    return abs(f+p.z-.5);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col=vec3(0.);
    vec2 uv=(fragCoord*2.-iResolution.xy)/iResolution.y;
    float mx=-(iMouse.x-abs(iMouse.z))/50.;
    float my=-(iMouse.y-abs(iMouse.w))/100.;

    vec3 r0=vec3(0.,0.,-1.4);
    r0.yz*=rot2d(my);
    r0.xz*=rot2d(mx);
    vec3 rd=normalize(vec3(uv,1.));
    rd.yz*=rot2d(my);
    rd.xz*=rot2d(mx);

    float maxdis=3.;
    float t=.5;
    int i=0;
    vec3 p=vec3(0.,0.,0.);
    int maxit=400;
    while(i<maxit)
    {
        p=r0+rd*t;

        float dis=map(p);
        //dis*=dis;
        t+=.005;
        if(dis<.05) break;
        if(t>maxdis) i=90;
        i++;
    }

    //col=palette(t*(8./maxdis));
    if(length(p.xy)<1.) col=palette(p.z*2.);
    if(i>=maxit)
    {
        col=vec3(0.,0.,0.);
    }    
    fragColor = vec4(col,1.);
}
